INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(54511, 'Judges 18:31', 'Judges', 18, 31, 'سره له دې چې د خدای کور په شیلوه کې ؤ، خو د دان خلکو هغه بت ته عبادت کاوه چې میخا جوړ کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_31.mp3', '', 1761754199, 1761754199),
(54512, 'Amos 2:1', 'Amos', 2, 1, 'څښتن داسې وایي: «د موآب خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی د ادوم د پاچا هډوکي وسوځول او هغه یې په ایرو باندې بدل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_1.mp3', '', 1761754199, 1761754199),
(54513, 'Amos 2:2', 'Amos', 2, 2, 'نو زه به د موآب په خلکو باندې اور نازل کړم او د قریوت د ښار قوي کلاګانې به وسوځوم. کله چې عسکر چیغې وهي او سرني وهل کیږي، نو د موآب خلک به د جنګ په شورماشور کې مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_2.mp3', '', 1761754199, 1761754199),
(54514, 'Amos 2:3', 'Amos', 2, 3, 'زه به د موآب حاکم له منځه یوسم او د وطن ټول مشران به وژنم.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_3.mp3', '', 1761754199, 1761754199),
(54515, 'Amos 2:4', 'Amos', 2, 4, 'څښتن داسې وایي: «د یهودا خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم، ځکه چې هغوی زما د شریعت سپکاوی کړی او زما په حکمونو باندې یې عمل نه دی کړی. هغوی د هماغو غلطو خدایانو په وسیله بې‌لارې شوي دي چې د هغوی نیکونو یې خدمت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_4.mp3', '', 1761754199, 1761754199),
(54516, 'Amos 2:5', 'Amos', 2, 5, 'نو زه به په یهودا باندې اور نازل کړم او د اورشلیم قوي کلاګانې به وسوځول شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_5.mp3', '', 1761754199, 1761754199),
(54517, 'Amos 2:6', 'Amos', 2, 6, 'څښتن داسې وایي: «د اسراییلو خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی هغه نېکان خلک په غلامۍ باندې خرڅوي چې خپل پورونه نه شي ورکولای او غریبان خلک چې حتی د یوې جوړې څپلیو بیه هم بېرته نه شي ورکولی، خرڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_6.mp3', '', 1761754199, 1761754199),
(54518, 'Amos 2:7', 'Amos', 2, 7, 'هغوی کمزوري او بې‌وسه خلک تر‌پښو لاندې کوي او غریبان په ټېل وهلو باندې د لارې څخه اخوا کوي. پلار او زوی دواړه د هماغې یوې انجلۍ سره څملي او زما د پاک نامه سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_7.mp3', '', 1761754199, 1761754199),
(54519, 'Amos 2:8', 'Amos', 2, 8, 'خلک د هر عبادتځای په خوا کې په هغو کالیو باندې څملي چې د غریبانو نه یې د پور په ضمانت کې اخیستي دي. هغوی د خپل خدای په کور کې په هغو پیسو باندې شراب څښي چې د خلکو څخه یې د جریمې په توګه اخیستي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_8.mp3', '', 1761754199, 1761754199),
(54520, 'Amos 2:9', 'Amos', 2, 9, 'خو بیاهم ای زما قومه، هغه زه وم چې ستاسو په خاطر مې هغه اموریان نابود کړل چې د سبر د ونو په شان لوړ قدي وو او د څېړیو د ونو په شان قوي وو. ما له څانګو نه مېوه تباه کړله او د هغو ریښې مې راووېستلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_9.mp3', '', 1761754199, 1761754199),
(54521, 'Amos 2:10', 'Amos', 2, 10, 'همدارنګه زه وم چې تاسو مې د مصر نه راوویستلئ او څلوېښت کاله مې په دښته کې ستاسو لارښوونه وکړه او ما د اموریانو ځمکه درکړه چې ستاسو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_10.mp3', '', 1761754199, 1761754199),
(54522, 'Amos 2:11', 'Amos', 2, 11, 'ستاسو د زامنو څخه مې ځینې غوره کړل چې پیغمبران شي او ځینې ځانګړي ځوانان د نذر شویو په توګه وقف کړل. ای د اسراییلو خلکو، ایا دا رښتیا نه دي؟ دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_11.mp3', '', 1761754199, 1761754199),
(54523, 'Amos 2:12', 'Amos', 2, 12, 'خو تاسو په هغو نذر شویو باندې شراب وڅښل او پیغمبرانو ته مو حکم وکړ چې پېشګویي ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_12.mp3', '', 1761754199, 1761754199),
(54524, 'Amos 2:13', 'Amos', 2, 13, 'نو ګورئ زه به تاسو په ځمکه راوولم او داسې زګېروي به کوئ لکه ګاډۍ چې د غلو دانو د بار لاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_13.mp3', '', 1761754199, 1761754199),
(54525, 'Amos 2:14', 'Amos', 2, 14, 'حتی هغه څوک چې تېزې منډې وهي، هغه هم نه شي تښتېدلی. قوي خلک به خپل قوت بایلي او عسکر به د دې توان نه لري چې خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_14.mp3', '', 1761754199, 1761754199),
(54526, 'Amos 2:15', 'Amos', 2, 15, 'غشي ویشتونکي به ټینګېدلی نه شي، تېز منډه وهونکي به ونه تښتي او په اسونو باندې سپاره خلک به خپل ځانونه خلاصولی نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_15.mp3', '', 1761754199, 1761754199),
(54527, 'Amos 2:16', 'Amos', 2, 16, 'په هغه ورځ به ډېر زړور عسکر هم خپلې وسلې په ځمکه وغورځوي او وبه تښتي. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos2_verse_16.mp3', '', 1761754199, 1761754199),
(54528, 'Joel 1:1', 'Joel', 1, 1, 'د مالِک خُدائ کلام چې په يوايل د فتوايل په زوئ نازل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_1.mp3', '', 1761754199, 1761754199),
(54529, 'Joel 1:2', 'Joel', 1, 2, 'اے مشرانو، دا واورئ. تاسو ټول غوږ شئ، څوک چې په دې مُلک کښې اوسېږئ. ولې ستاسو په ژوند کښې يا ستاسو د پلار نيکۀ په ژوند کښې داسې څۀ کله پېښ شوى دى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_2.mp3', '', 1761754199, 1761754199),
(54530, 'Joel 1:3', 'Joel', 1, 3, 'دا خپل اولاد ته ووايئ، او هغوئ دې دا خپل اولاد ته ووائى او داسې دې دا ياد تر نسلونو پورې تازه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_3.mp3', '', 1761754199, 1761754199),
(54531, 'Joel 1:4', 'Joel', 1, 4, 'د قحطۍ د مُلخانو د لښکرو نه چې څۀ پاتې شُو، هغه غټو مُلخانو وخوړل، چې د غټو مُلخانو نه څۀ پاتې شُو نو هغه وړو مُلخانو وخوړل، او څۀ چې د وړو مُلخانو نه پاتې شُو، نو هغه نورو مُلخانو وخوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_4.mp3', '', 1761754199, 1761754199),
(54532, 'Joel 1:5', 'Joel', 1, 5, 'اے شرابيانو، ويښ شئ او وژاړئ، اے مے څښونکو، تاسو ټول افسوس وکړئ، د نوؤ ميو په وجه افسوس وکړئ، ځکه چې دا ستاسو د شونډو نه راښکلے شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_5.mp3', '', 1761754199, 1761754199),
(54533, 'Joel 1:6', 'Joel', 1, 6, 'د هغوئ ټول لښکر زما په مُلک حمله وکړه، چې طاقتور او د شمېر نه بهر دى، د هغوئ غاښونه د زمرى په شان تېرۀ دى او د هغوئ داړې د زمرۍ په شان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_6.mp3', '', 1761754199, 1761754199),
(54534, 'Joel 1:7', 'Joel', 1, 7, 'هغوئ زما د انګورو بوټى تباه کړى دى او زما د اينځرو ونې يې تباه کړې دى، پوستکى يې ترې نه ويستى دى او تباه کړى يې دى، د دې څانګې يې خالى او لغړى پرېښودې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_7.mp3', '', 1761754199, 1761754199),
(54535, 'Joel 1:8', 'Joel', 1, 8, 'لکه د هغه پېغلې وژاړئ چا چې د ماتم جامې اغوستې وى او د خپل چنغول په مرګ ژړا انګولا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_8.mp3', '', 1761754199, 1761754199),
(54536, 'Joel 1:9', 'Joel', 1, 9, 'د غلې او د څښلو نذرانې د مالِک خُدائ په کور کښې ختمې شوې. هغه اِمامان ژاړى څوک چې د مالِک خُدائ په وړاندې خِدمت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_9.mp3', '', 1761754199, 1761754199),
(54537, 'Joel 1:10', 'Joel', 1, 10, 'پټى تباه شوى دى، زمکه اوچه شوه، غله تباه شوه، انګور ضائع شُو، او د زيتُونو تېل ختم شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_10.mp3', '', 1761754199, 1761754199),
(54538, 'Joel 1:11', 'Joel', 1, 11, 'اے زميدارانو غمژن اوسئ، اے د انګورو د باغ ماليانو، ژړا کوئ، د غنم او د اوربشو دپاره غمژن شئ، ځکه چې د فصل پټى تباه شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_11.mp3', '', 1761754199, 1761754199),
(54539, 'Joel 1:12', 'Joel', 1, 12, 'د انګورو بوټى اوچ شُو او د اينځرو ونې وچې شوې، د انارو ونې، د کجورو ونې، او د سيوانو ونې او ټولې مېوه دارې ونې وچې شوې دى. او يقيناً د خلقو خوشحالى ورسره ورکه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_12.mp3', '', 1761754199, 1761754199),
(54540, 'Joel 1:13', 'Joel', 1, 13, 'اے اِمامانو د ټاټ جامې واچوئ او وژاړئ، او ماتم وکړئ تاسو څوک چې په قربان‌ګاه کښې خِدمت کوئ. راشئ، ټوله شپه د ټاټ په جامو کښې تېره کړئ، تاسو څوک چې د مالِک خُدائ په حضور کښې خِدمت کوئ. ځکه چې ستاسو د خُدائ کور د غلې او د څښلو د نذرانو نه محروم شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_13.mp3', '', 1761754199, 1761754199),
(54541, 'Joel 1:14', 'Joel', 1, 14, 'د مقدسې روژې نيولو اعلان وکړئ، او د خلقو مقدسه اجتماع راوغواړئ. مشران او د مُلک ټول خلق د مالِک خُدائ د خپل خُدائ پاک کور ته راوغواړئ او مالِک خُدائ ته وژاړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_14.mp3', '', 1761754199, 1761754199),
(54542, 'Joel 1:15', 'Joel', 1, 15, 'افسوس په هغه ورځ، ځکه چې د مالِک خُدائ هغه د قيامت ورځ رانزدې ده، په کومه به چې قادر خُدائ تباهى راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_15.mp3', '', 1761754199, 1761754199),
(54543, 'Joel 1:16', 'Joel', 1, 16, 'زمونږ خوراک زمونږ د سترګو په وړاندې غېب شو، او خندا خوشحالى زمونږ د خُدائ پاک په کور کښې بنده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_16.mp3', '', 1761754199, 1761754199),
(54544, 'Joel 1:17', 'Joel', 1, 17, 'تخم د زمکې لاندې اوچ شو. د غلې ګودامونه خالى او وران ويجاړ پراتۀ دى، خمبې تشې او ماتې شوې ځکه چې تخم اوچ شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_17.mp3', '', 1761754199, 1761754199),
(54545, 'Joel 1:18', 'Joel', 1, 18, 'څاروى د لوږې نه چغې وهى، د څاروو رمې اخوا ديخوا پرېشانه ګرځى ځکه چې د هغوئ دپاره شينکے نشته، تر دې چې د ګډو رمې هم په تکليف کښې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_18.mp3', '', 1761754199, 1761754199),
(54546, 'Joel 1:19', 'Joel', 1, 19, 'اے مالِکه خُدايه، زۀ تا ته د مدد دپاره فرياد کوم، ځکه چې اور د څرېدو ځايونه وسوزول او لمبو د ټولو پټو ونې وسوزولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_19.mp3', '', 1761754199, 1761754199),
(54547, 'Joel 1:20', 'Joel', 1, 20, 'تر دې چې ځنګلى ځناور هم تا ته فرياد کوى ځکه چې د اوبو نِهرونه اوچ شوى دى، او د اور لمبو په صحرا کښې څرن ځايونه سوزولى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel1_verse_20.mp3', '', 1761754199, 1761754199),
(54548, 'Psalms 1:1', 'Psalms', 1, 1, 'چې عمل د بد عملو په ویناوو باندې نه کړي نه په لار د ګناهکارو باندې درومي مسخرو ډلو کې هم کښېناستل نه کړي نو بیا هغه بختور دی بختور دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_1.mp3', '', 1761754199, 1761754199),
(54549, 'Psalms 1:2', 'Psalms', 1, 2, 'خو شریعت کې د څښتن چې خوشحالیږي شپه او ورځ کاندي فکرونه په هغې کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_2.mp3', '', 1761754199, 1761754199),
(54550, 'Psalms 1:3', 'Psalms', 1, 3, 'په مثال د هغې ونې دی دا شخص چې ولاړه د ویالې په غاړه شنه وي چې مېوه نیسي په خپل وخت کې مدام نه یې کله پاڼې وچې ښکاره کیږي بریالی وي په هر کار کې چې یې کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_3.mp3', '', 1761754199, 1761754199),
(54551, 'Psalms 1:4', 'Psalms', 1, 4, 'بدکاران داسې هېڅکله نه ښکاریږي ځکه هر خواته د بوس غوندې بادیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_4.mp3', '', 1761754199, 1761754199),
(54552, 'Psalms 1:5', 'Psalms', 1, 5, 'دغه راز به خدای محکوم ګناهکاران کړي هم به یې هغه د خپله قومه جدا کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_5.mp3', '', 1761754199, 1761754199),
(54553, 'Psalms 1:6', 'Psalms', 1, 6, 'څښتن ته معلومه ده د نېکانو لاره بدکاران به تباهۍ ته ور روان شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms1_verse_6.mp3', '', 1761754199, 1761754199),
(54554, 'Psalms 90:1', 'Psalms', 90, 1, 'تل پناه ځای یې زمونږ د ټولو نسلو ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_1.mp3', '', 1761754199, 1761754199),
(54555, 'Psalms 90:2', 'Psalms', 90, 2, 'مخکې له دې نه چې ته غرونه او یا ځمکه او نړۍ پیدا کړې ته له ازله تر ابده خدای یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_2.mp3', '', 1761754199, 1761754199),
(54556, 'Psalms 90:3', 'Psalms', 90, 3, 'ته انسان بېرته ورولې خاورو ته، وایې ورته: «خاورو ته ستون شه ای فاني انسانه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_3.mp3', '', 1761754199, 1761754199),
(54557, 'Psalms 90:4', 'Psalms', 90, 4, 'ستا په نظر کې زر کلونه داسې ښکاري لکه یوه ورځ د پرون ورځې په شان چې تېره شوې وي او یا لکه د شپې د پهرې وار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_4.mp3', '', 1761754199, 1761754199),
(54558, 'Psalms 90:5', 'Psalms', 90, 5, 'ته ناڅاپه انسانان له منځه وړې د هغوی عمر لنډ وي لکه د خوب په شان یا د هغو واښو په شان چې ځي له منځه زر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_5.mp3', '', 1761754199, 1761754199),
(54559, 'Psalms 90:6', 'Psalms', 90, 6, 'چې راشنه کیږي په سهار کې او غټیږي هم بیا مړاوي کیږي په ماښام کې او وچیږي هم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_6.mp3', '', 1761754199, 1761754199),
(54560, 'Psalms 90:7', 'Psalms', 90, 7, 'بربادوي مونږ ستا قهر سخت وېروي مونږه ستا غضب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_7.mp3', '', 1761754199, 1761754199),
(54561, 'Psalms 90:8', 'Psalms', 90, 8, 'تا خپلې مخې ته دي ایښي ګناهونه زمونږه پټ ګناهونه زمونږ ښکاره دي تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_8.mp3', '', 1761754199, 1761754199),
(54562, 'Psalms 90:9', 'Psalms', 90, 9, 'عمر تېریږي زمونږ ستا په غضب کې په اوسېلو کې مو ژوند پای مومي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_9.mp3', '', 1761754199, 1761754199),
(54563, 'Psalms 90:10', 'Psalms', 90, 10, 'زمونږه عمر به اویا کاله وي او یا اتیا د ښې روغتیا په سبب خو هغه ټول د کړاوونو او دردونو سره مونږ فنا کېږو هغه زر تېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_10.mp3', '', 1761754199, 1761754199),
(54564, 'Psalms 90:11', 'Psalms', 90, 11, 'څوک ستا د قهر په قوت پوهیږي؟ څوک ستا په غضب پوهیږي او وېریږي ترې؟ ځکه چې ستا نه باید ووېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_11.mp3', '', 1761754199, 1761754199),
(54565, 'Psalms 90:12', 'Psalms', 90, 12, 'کړه مو ته پوه چې څومره عمر لرو ترڅو شو مونږه هوښیار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_12.mp3', '', 1761754199, 1761754199),
(54566, 'Psalms 90:13', 'Psalms', 90, 13, 'ای څښتنه، وي به ستا قهر تر کومه؟ بس کړه، په خپلو خادمانو دې زړه وسوځه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_13.mp3', '', 1761754199, 1761754199),
(54567, 'Psalms 90:14', 'Psalms', 90, 14, 'ستا په تلپاتې مینه هر سهار ماړه کړه مونږه ترڅو خپل ټول عمر کړو تېر په خوشحالۍ او په سندرو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_14.mp3', '', 1761754199, 1761754199),
(54568, 'Psalms 90:15', 'Psalms', 90, 15, 'اوس مونږ ته دومره خوشحالي راکړه لکه راکړي کړاوونه دې وو څومره ورځې څومره کلونه چې راکړې دې وې مونږ ته ستونزې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_15.mp3', '', 1761754199, 1761754199),
(54569, 'Psalms 90:16', 'Psalms', 90, 16, 'پرېږده چې وویني ستا بندګان ستا زورور کارونه او اولاده زمونږه وګوري دا ستا لویي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_16.mp3', '', 1761754199, 1761754199),
(54570, 'Psalms 90:17', 'Psalms', 90, 17, 'ای زمونږ څښتنه خدایه وي ستا ښېګڼې دې زمونږه سره ټولو کارونو کې بریا راکړه هو، مونږ ته بریا راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms90_verse_17.mp3', '', 1761754199, 1761754199);